INSERT INTO kb_entries(merchant_id,category_id,intent_key,title,topic,aspect,topic_optional) VALUES((SELECT id FROM merchants WHERE code='MERCH_A'),(SELECT id FROM kb_categories WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND name='Deposit'),'deposit_how','deposit how','deposit','how',false);
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='deposit_how'),'en',ARRAY['how to deposit','how to dep','depo how','how topup','deps how to do','cara nak top up'],'To deposit, go to Wallet > Deposit, choose a payment method and follow the steps.');
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='deposit_how'),'ms',ARRAY['macam mana nak deposit','cara depo','nak dep macam mana','cara top up'],'Untuk deposit, pergi ke Wallet > Deposit, pilih kaedah pembayaran dan ikut langkah yang diberi.');
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='deposit_how'),'zh',ARRAY['怎么存款','如何充值','怎样存钱','充值方法'],'存款请前往Wallet > Deposit，选择付款方式并按步骤操作。');
INSERT INTO kb_entries(merchant_id,category_id,intent_key,title,topic,aspect,topic_optional) VALUES((SELECT id FROM merchants WHERE code='MERCH_A'),(SELECT id FROM kb_categories WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND name='Deposit'),'deposit_time','deposit time','deposit','time',false);
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='deposit_time'),'en',ARRAY['how long deposit take','dep not arrive','depo still pending','when deposit arrive'],'Deposits are usually credited within 5 minutes. If it takes longer, please send us your payment receipt.');
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='deposit_time'),'ms',ARRAY['berapa lama deposit masuk','depo belum masuk','deposit lambat'],'Deposit biasanya dikreditkan dalam masa 5 minit. Jika lebih lama, sila hantar resit pembayaran anda.');
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='deposit_time'),'zh',ARRAY['存款多久到账','充值还没到','存款怎么还没到账'],'存款通常在5分钟内到账。如果超过这个时间，请把付款凭证发给我们。');
INSERT INTO kb_entries(merchant_id,category_id,intent_key,title,topic,aspect,topic_optional) VALUES((SELECT id FROM merchants WHERE code='MERCH_A'),(SELECT id FROM kb_categories WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND name='Deposit'),'deposit_limit','deposit limit','deposit','limit',false);
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='deposit_limit'),'en',ARRAY['minimum deposit','min dep','max deposit','deposit limit'],'The minimum deposit is MYR 10 and the maximum per transaction is MYR 30,000.');
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='deposit_limit'),'ms',ARRAY['deposit minimum berapa','min depo','had deposit'],'Deposit minimum ialah MYR 10 dan maksimum setiap transaksi ialah MYR 30,000.');
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='deposit_limit'),'zh',ARRAY['最低存款','最少充值多少','存款限额'],'最低存款金额为MYR 10，单笔最高为MYR 30,000。');
INSERT INTO kb_entries(merchant_id,category_id,intent_key,title,topic,aspect,topic_optional) VALUES((SELECT id FROM merchants WHERE code='MERCH_A'),(SELECT id FROM kb_categories WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND name='Withdrawal'),'withdraw_how','withdraw how','withdraw','how',false);
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='withdraw_how'),'en',ARRAY['how to withdraw','how wd','how to wdraw','cash out how'],'To withdraw, go to Wallet > Withdraw, enter the amount and your bank account, then submit.');
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='withdraw_how'),'ms',ARRAY['macam mana nak tarik duit','cara wd','nak withdraw macam mana'],'Untuk pengeluaran, pergi ke Wallet > Withdraw, masukkan jumlah dan akaun bank anda, kemudian hantar.');
INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='withdraw_how'),'zh',ARRAY['怎么提款','如何取款','提现方法'],'提款请前往Wallet > Withdraw，输入金额和银行账户后提交。');
INSERT INTO kb_entries(merchant_id,category_id,intent_key,title,topic,aspect,topic_optional) VALUES((SELECT id FROM merchants WHERE code='MERCH_A'),(SELECT id FROM kb_categories WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND name='Withdrawal'),'withdraw_time','withdraw time','withdraw','time',false);
