INSERT INTO kb_translations(kb_id,language,question_examples,answer_text) VALUES((SELECT id FROM kb_entries WHERE merchant_id=(SELECT id FROM merchants WHERE code='MERCH_A') AND intent_key='withdraw_time'),'ms',ARRAY['berapa lama withdraw','wd belum masuk','tarikan lambat'],'Pengeluaran diproses dalam masa 30 minit.');
